const DISCLAIMER = 'Déclaration criminelle non vérifiée ; aucune compromission n’est confirmée.';
const fallback = () => ({language:'fr',summary_fr:'Une ou plusieurs sources publiques relaient une déclaration concernant l’organisation surveillée. Les preuves disponibles ne confirment pas une compromission.',observed_facts:[],uncertainties:['Analyse locale indisponible ou invalide ; consulter les preuves sources.'],disclaimer:DISCLAIMER});
const allowed = new Set((source.input_payload.observations ?? []).map(item => item.evidence_id));
const forbidden = /https?:\/\/|confidence_score|verification_status|auto_alert_eligible|compromission\s+(?:est\s+)?confirmée|incident\s+(?:est\s+)?confirmé/i;
const validate = payload => {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
  const keys = Object.keys(payload).sort().join(',');
  if (keys !== ['disclaimer','language','observed_facts','summary_fr','uncertainties'].join(',')) return false;
  if (payload.language !== 'fr' || payload.disclaimer !== DISCLAIMER || typeof payload.summary_fr !== 'string' || payload.summary_fr.length < 1 || payload.summary_fr.length > 600) return false;
  if (!Array.isArray(payload.observed_facts) || payload.observed_facts.length > 5 || !Array.isArray(payload.uncertainties) || payload.uncertainties.length > 5) return false;
  const texts = [payload.summary_fr, ...payload.uncertainties];
  for (const fact of payload.observed_facts) {
    if (!fact || Object.keys(fact).sort().join(',') !== 'evidence_ids,statement_fr' || typeof fact.statement_fr !== 'string' || fact.statement_fr.length < 1 || fact.statement_fr.length > 240) return false;
    if (!Array.isArray(fact.evidence_ids) || fact.evidence_ids.length < 1 || fact.evidence_ids.length > 10 || new Set(fact.evidence_ids).size !== fact.evidence_ids.length || fact.evidence_ids.some(id => !allowed.has(id))) return false;
    texts.push(fact.statement_fr);
  }
  if (payload.uncertainties.some(value => typeof value !== 'string' || value.length < 1 || value.length > 200) || new Set(payload.uncertainties).size !== payload.uncertainties.length) return false;
  return !texts.some(value => forbidden.test(value));
};
let output;
try { output = JSON.parse($json.message?.content ?? ''); } catch { output = null; }
const valid = validate(output);
return {json:{persistence:{claim_id:source.claim_id,evidence_version:source.evidence_version,model_name:source.model_name,model_digest:source.model_digest,prompt_version:source.prompt_version,input_payload:source.input_payload,input_hash:source.input_hash,output_payload:valid?output:fallback(),validation_status:valid?'valid':'fallback',failure_code:valid?null:'model_output_invalid',inference_metadata:valid?{done_reason:$json.done_reason,prompt_tokens:$json.prompt_eval_count,output_tokens:$json.eval_count,total_duration_ns:$json.total_duration}:{}}}};

